namespace gui_forms {

// TabControl's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/tab_control.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The edge the tabs sit on (Windows Forms' Alignment; default top). An unknown alignment throws std::invalid_argument.
template <typename Declaring>
struct TabControlAlignmentCapability {
    PropertyCell<TabAlignment, TabControlAlignmentCapability<Declaring>> alignment{TabAlignment::top};

    static void assign(TabControlAlignmentCapability& capability, TabAlignment incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.alignment), incoming);
        if (!capability.alignment.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.alignment));
    }
};

// How the tabs are drawn (see TabAppearance; default normal). An unknown appearance throws std::invalid_argument.
template <typename Declaring>
struct TabControlAppearanceCapability {
    PropertyCell<TabAppearance, TabControlAppearanceCapability<Declaring>> appearance{TabAppearance::normal};

    static void assign(TabControlAppearanceCapability& capability, TabAppearance incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.appearance), incoming);
        if (!capability.appearance.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.appearance));
    }
};

// How wide each tab is (see TabSizeMode; default normal). An unknown mode throws std::invalid_argument.
template <typename Declaring>
struct TabControlSizeModeCapability {
    PropertyCell<TabSizeMode, TabControlSizeModeCapability<Declaring>> size_mode{TabSizeMode::normal};

    static void assign(TabControlSizeModeCapability& capability, TabSizeMode incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.size_mode), incoming);
        if (!capability.size_mode.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.size_mode));
    }
};

// A tab's size: its height across the row, and its width along it in TabSizeMode::fixed (default 120 by 30). A size that is not finite, under 24 by 18 or over 1024 by 1024 throws std::invalid_argument.
template <typename Declaring>
struct TabControlItemSizeCapability {
    PropertyCell<Size, TabControlItemSizeCapability<Declaring>> item_size{Size{120.0, 30.0}};

    static void assign(TabControlItemSizeCapability& capability, Size incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.item_size), incoming);
        if (!capability.item_size.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.item_size));
    }
};

// The images the pages' image_key and image_index name (Windows Forms' ImageList), or null; a tab shows its image before its text. A disposed list or one belonging to another window throws std::invalid_argument and keeps the old list.
template <typename Declaring>
struct TabControlImageListCapability {
    PropertyCell<std::shared_ptr<ImageList>, TabControlImageListCapability<Declaring>> image_list{};

    static void assign(TabControlImageListCapability& capability, std::shared_ptr<ImageList> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.image_list), incoming);
        if (!capability.image_list.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.image_list));
    }
};

// Content-only owner drawing of the tabs (owner decision W-Q6; Windows Forms' DrawMode with DrawItem), the strip's: in ItemDrawMode::owner_draw draw_item_content is raised for each painted tab's icon and label, with the tab's index and its page's stable ID; the tab's plate and focus cue stay painted by role. See PageStrip::draw_item_content.
template <typename Declaring>
struct TabControlDrawModeCapability {
    PropertyView<ItemDrawMode, TabControlDrawModeCapability<Declaring>> draw_mode;

    static void assign(TabControlDrawModeCapability& capability, ItemDrawMode incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.draw_mode), std::move(incoming));
    }

    static ItemDrawMode read(const TabControlDrawModeCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        ItemDrawMode current = control.read_view(capability.draw_mode);
        return current;
    }
};

// Every TabControl capability, in the order the declaring class takes them.
template <typename Declaring>
struct TabControlCapabilities : public TabControlAlignmentCapability<Declaring>,
                                public TabControlAppearanceCapability<Declaring>,
                                public TabControlSizeModeCapability<Declaring>,
                                public TabControlItemSizeCapability<Declaring>,
                                public TabControlImageListCapability<Declaring>,
                                public TabControlDrawModeCapability<Declaring> {};

} // namespace gui_forms
